using UnityEngine;using UnityEditor;using System.IO;using System.Collections.Generic;
[InitializeOnLoad]public static class KeyPickupInspect{
 static KeyPickupInspect(){EditorApplication.delayCall+=()=>{if(!File.Exists("Temp/key_pickup_inspect.request"))return;File.Delete("Temp/key_pickup_inspect.request");var lines=new List<string>();foreach(var k in Object.FindObjectsByType<StealthGame.Key>(FindObjectsInactive.Include,FindObjectsSortMode.None)){lines.Add(k.name+" key="+k.KeyName+" position="+k.transform.position+" scale="+k.transform.lossyScale+" active="+k.gameObject.activeInHierarchy+" enabled="+k.enabled);foreach(var c in k.GetComponentsInChildren<Collider>(true))lines.Add(" collider="+c.GetType().Name+" enabled="+c.enabled+" trigger="+c.isTrigger+" bounds="+c.bounds);foreach(var r in k.GetComponentsInChildren<Renderer>())lines.Add(" visual="+r.name+" bounds="+r.bounds);}var p=GameObject.Find("Player");foreach(var c in p.GetComponentsInChildren<Collider>())lines.Add("PLAYER "+c.name+" "+c.bounds);File.WriteAllLines("Temp/key_pickup_inspect.txt",lines);};}
}
